sp_widget.client_script:
api.controller = function(spModal, $scope) {
  var c = this;

  // Post a new comment to the activity stream
  c.addComment = function(item) {
    if (!item.newComment) return;

    c.data.sys_id = item.sys_id;
    c.data.action = 'add_comment';
    c.data.comment = item.newComment;

    c.server.update().then(function() {
        item.newComment = ""; // Clear input field on success
    });
  };

  // Open the decision modal (Approve/Reject)
  c.openModal = function(item, type) {
    var isApprove = (type === 'approve');
    var title = isApprove ? 'Approve Request' : 'Reject Request';
    var btnClass = isApprove ? 'btn-success' : 'btn-danger';
    var btnLabel = isApprove ? 'Confirm Approve' : 'Confirm Reject';

    spModal.open({
      title: title,
      message: 'Please provide a reason or additional notes:',
      input: true,
      buttons: [
        {label: 'Cancel', cancel: true},
        {label: btnLabel, primary: true, class: btnClass}
      ]
    }).then(function(reason) {
        c.data.sys_id = item.sys_id;
        c.data.action = isApprove ? 'approved' : 'rejected';
        c.data.comment = reason;
        c.server.update();
    });
  };
};

sp_widget.css:
.approval-portal-wrapper {
  max-width: 950px;
  margin: 0 auto;
  padding: 20px;

  .approval-card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 20px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.05);

    .card-meta {
      display: flex;
      gap: 10px;
      margin-bottom: 12px;
      align-items: center;
      .record-num { color: #64748b; font-weight: 600; font-size: 13px; }
    }

    .badge {
      padding: 4px 12px;
      border-radius: 100px;
      font-size: 12px;
      &.badge-priority.high { background: #fee2e2; color: #b91c1c; }
      &.badge-status { background: #f1f5f9; color: #475569; }
      &.badge-type { border: 1px solid #e2e8f0; background: #fff; color: #475569; }
    }

    .action-footer {
      display: flex;
      justify-content: space-between;
      border-top: 1px solid #f1f5f9;
      padding-top: 20px;
      margin-top: 20px;
    }

    .btn-approve { background: #528574; color: #fff; border: none; border-radius: 6px; padding: 8px 16px; margin-right: 8px; }
    .btn-reject { background: #b91c1c; color: #fff; border: none; border-radius: 6px; padding: 8px 16px; margin-right: 8px; }
    .btn-view { background: #fff; border: 1px solid #e2e8f0; border-radius: 6px; padding: 8px 16px; }

    .comment-section {
      margin-top: 15px;
      background: #f8fafc;
      padding: 15px;
      border-radius: 8px;

      .comment-item {
        background: #fff;
        padding: 10px;
        border-radius: 6px;
        border-left: 3px solid #3b82f6;
        margin-bottom: 10px;
      }

      .comment-input-group {
        position: relative;
        margin-top: 15px;
        input { border-radius: 25px; padding-right: 45px; height: 40px; }
        .btn-send { position: absolute; right: 5px; top: 4px; background: #3b82f6; color: #fff; border-radius: 50%; width: 32px; height: 32px; padding: 0; }
      }
    }
  }
}

sp_widget.script:
(function() {
    data.approvals = [];
    var loggedInUser = gs.getUserID();

    // Handle Input Actions
    if (input) {
        var grAction = new GlideRecord('sysapproval_approver');
        if (grAction.get(input.sys_id)) {
            // 1. Process Approval or Rejection
            if (input.action === 'approved' || input.action === 'rejected') {
                grAction.state = input.action;
                grAction.comments = input.comment;
                grAction.update();
            }

            // 2. Process New Comment Posting
            if (input.action === 'add_comment' && input.comment) {
                var taskGr = new GlideRecord('task'); 
                if (taskGr.get(grAction.sysapproval)) {
                    taskGr.comments = input.comment;
                    taskGr.update();
                }
            }
        }
    }

    // Fetch all 'Requested' approvals
    var gr = new GlideRecord('sysapproval_approver');
    gr.addQuery('approver', loggedInUser);
    gr.addQuery('state', 'requested');
    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {
        var obj = {
            sys_id: gr.getUniqueValue(),
            target_sys_id: gr.sysapproval.toString(),
            number: gr.sysapproval.getDisplayValue(),
            short_description: gr.sysapproval.short_description.getDisplayValue(),
            description: gr.sysapproval.description.getDisplayValue(),
            opened_by: gr.sysapproval.opened_by.getDisplayValue(),
            created: gr.sysapproval.sys_created_on.getDisplayValue(),
            priority: gr.sysapproval.priority.getDisplayValue(),
            type: gr.sysapproval.sys_class_name.getDisplayValue(),
            comments: []
        };

        // Fetch all previous journal comments
        var mgr = new GlideRecord('sys_journal_field');
        mgr.addQuery('element_id', gr.sysapproval.sys_id);
        mgr.addQuery('element', 'comments');
        mgr.orderByDesc('sys_created_on');
        mgr.query();

        while(mgr.next()){
            obj.comments.push({
                user: mgr.sys_created_by.toString(),
                text: mgr.value.toString(),
                date: mgr.sys_created_on.getDisplayValue()
            });
        }
        data.approvals.push(obj);
    }
})();
